module multi_pipe_8bit(
    input clk, 
    input rst_n, 
    input mul_en_in, 
    input [7:0] mul_a, 
    input [7:0] mul_b, 
    output mul_en_out, 
    output [15:0] mul_out
);
// Define parameters for states
parameter IDLE = 2'b00;
parameter LOAD = 2'b01;
parameter CALC = 2'b10;
parameter OUT = 2'b11;
// Define registers for storing input values
reg [1:0] mul_en_out_reg;
reg [7:0] mul_a_reg;
reg [7:0] mul_b_reg;
// Define registers for storing partial sums
reg [15:0] sum [0:7];
// Define registers for storing final product
reg [15:0] mul_out_reg;
// Define wires for storing temporary values
wire [15:0] temp [0:7];
// Sequential logic for updating output enable signal
always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        mul_en_out_reg <= 2'b0;
    end else begin
        mul_en_out_reg <= {mul_en_out_reg[0], mul_en_in};
    end
end
// Sequential logic for loading input values into registers
always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        mul_a_reg <= 8'h0;
        mul_b_reg <= 8'h0;
    end else if (mul_en_in) begin
        mul_a_reg <= mul_a;
        mul_b_reg <= mul_b;
    end
end
// Combinational logic for generating partial products
assign temp[0] = mul_b_reg[0] ? {8'h0, mul_a_reg} : 16'h0;
assign temp[1] = mul_b_reg[1] ? {7'h0, mul_a_reg, 1'b0} : 16'h0;
assign temp[2] = mul_b_reg[2] ? {6'h0, mul_a_reg, 2'b00} : 16'h0;
assign temp[3] = mul_b_reg[3] ? {5'h0, mul_a_reg, 3'b000} : 16'h0;
assign temp[4] = mul_b_reg[4] ? {4'h0, mul_a_reg, 4'b0000} : 16'h0;
assign temp[5] = mul_b_reg[5] ? {3'h0, mul_a_reg, 5'b00000} : 16'h0;
assign temp[6] = mul_b_reg[6] ? {2'h0, mul_a_reg, 6'b000000} : 16'h0;
assign temp[7] = mul_b_reg[7] ? {1'b0, mul_a_reg, 7'b0000000} : 16'h0;
// Sequential logic for calculating partial sums
always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        sum[0] <= 16'h0;
        sum[1] <= 16'h0;
        sum[2] <= 16'h0;
        sum[3] <= 16'h0;
        sum[4] <= 16'h0;
        sum[5] <= 16'h0;
        sum[6] <= 16'h0;
        sum[7] <= 16'h0;
    end else begin
        sum[0] <= temp[0];
        sum[1] <= sum[0] + temp[1];
        sum[2] <= sum[1] + temp[2];
        sum[3] <= sum[2] + temp[3];
        sum[4] <= sum[3] + temp[4];
        sum[5] <= sum[4] + temp[5];
        sum[6] <= sum[5] + temp[6];
        sum[7] <= sum[6] + temp[7];
    end
end
// Sequential logic for calculating final product
always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        mul_out_reg <= 16'h0;
    end else begin
        mul_out_reg <= sum[0] + sum[1] + sum[2] + sum[3] + sum[4] + sum[5] + sum[6] + sum[7];
    end
end
// Assign output product value
assign mul_out = mul_en_out_reg[1] ? mul_out_reg : 16'h0;
endmodule
